in_real.rs.src:
fn average(readings: &[f64]) -> f64 {
    let mut sum = 0.0;
    for r in readings {
        sum += *r;
    }
    sum / readings.len() as f64
}

fn main() {
    let week = vec![18.0, 21.0, 19.5, 22.5, 24.0, 20.0, 23.0];
    println!("whole week: {:.1}", average(&week));
    println!("weekend:    {:.1}", average(&week[5..]));
    println!("first 3:    {:.1}", average(&week[..3]));
}

